(function(){
'use strict';
const U=RWAIUtils,L=(z,e)=>RWI18n.lang==='en'?e:z,E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),H='https://aihorde.net/api/v2',O='https://openrouter.ai/api/v1';
let catalog,knowledge,chatBusy=false,imageBusy=false,job=null,pollTimer,sourceImage='',sourceName='',resultURL='',resultData='',chatAbort,chat=[],draft='',preset='unit',idea='';
const $=s=>document.querySelector(s),note=s=>window.toast?.(s),get=(k,f)=>{try{return JSON.parse(sessionStorage.getItem(k))??f}catch{return f}},set=(k,v)=>{try{sessionStorage.setItem(k,JSON.stringify(v))}catch{}};
chat=get('rwlab-ai-chat',[]);job=get('rwlab-ai-job',null);draft=get('rwlab-ai-draft','');
function credentials(){return get('rwlab-ai-keys',{})}
async function json(url,options={}){const r=await fetch(url,{...options,signal:options.signal||AbortSignal.timeout(45000)});let body;try{body=await r.json()}catch{throw Error('HTTP '+r.status)}if(!r.ok)throw Error(body.message||body.error?.message||'HTTP '+r.status);return body}
async function models(){if(catalog)return catalog;catalog=await json('ai-models.json');return catalog}
function blankImage(){return `<div class="ai-placeholder"><b>✦</b><h2>${L('从一句想法开始','Start with an idea')}</h2><p>${L('选择用途，补充外观细节，让免费云端模型生成草图，再到像素编辑器里修整','Pick a sprite or terrain preset, describe the details, then refine the result in the pixel editor')}</p></div>`}
function status(text){const e=$('#ai-image-status');if(e)e.textContent=text}
async function mount(page){if(page==='settings')return settingsPage();if(page==='ai-help')return helpPage();imagePage();try{const c=await models();fillImageModels(c);if(job){imageBusy=true;status(L('继续等待上一张图片','Resuming your previous image'));poll()}}catch(e){status(e.message)}}
function imagePage(){$('#main').innerHTML=`<div class="creative-shell"><div class="creative-title"><div><a class="ed-back" href="#editors">← ${L('创作工具','Creative tools')}</a><div class="eyebrow">FREE CLOUD / RUSTED WARFARE ART</div><h1>${L('AI 图形编辑器','AI art studio')}</h1><p>${L('不会画也能开始，选择铁锈战争风格模板，用文字生成或修改草图','Start without drawing skills, use Rusted Warfare style presets to generate or revise a draft')}</p></div><a class="btn btn-plain" href="#settings">${L('设置密钥','API key settings')}</a></div><div class="ai-layout"><section class="ai-panel"><h2>${L('想做什么素材','What are you making?')}</h2><div class="ai-presets">${Object.entries(U.presets).map(([k,v])=>`<button data-ai="preset" data-value="${k}" aria-pressed="${preset===k}">${E(v[RWI18n.lang])}</button>`).join('')}</div><label for="ai-idea">${L('补充你的想法','Describe your idea')}</label><textarea id="ai-idea" placeholder="${L('例如：有两条履带的小型侦察车，绿色装甲，炮管朝上','For example: a compact tracked scout with green armor and an upward-pointing gun')}">${E(idea)}</textarea><label for="ai-image-model">${L('免费绘图模型','Free image model')}</label><select id="ai-image-model"><option>${L('正在读取模型','Loading models')}</option></select><p id="ai-model-note"></p><label>${L('已有草图？上传后修改','Have a draft? Upload it to edit')}<input id="ai-source" type="file" accept="image/png,image/jpeg,image/webp"></label><small id="ai-source-name">${E(sourceName)||L('可选，使用原图的轮廓和配色','Optional, retain your draft’s composition and colors')}</small><button class="btn btn-small btn-plain" data-ai="remove-source">${L('移除参考图','Remove reference')}</button><label for="ai-strength">${L('修改幅度','How much should change?')}</label><input id="ai-strength" type="range" min="0.1" max="0.9" step="0.05" value="0.5"><label><input id="ai-anonymous" type="checkbox"> ${L('使用匿名免费队列','Use the anonymous free queue')}</label><p>${L('匿名模式会公开分享提示词和生成图用于研究，请勿上传私人图片，使用个人免费密钥时不公开分享，志愿者服务仍会处理内容','Anonymous requests share prompts and generated images for research, do not upload private images, a personal free key disables public sharing, volunteer workers still process your content')}</p><div class="detail-actions"><button class="btn btn-orange" data-ai="generate">✦ ${L('免费生成','Generate for free')}</button><button class="btn btn-plain" data-ai="cancel-image" ${!job?'disabled':''}>${L('取消排队','Cancel request')}</button></div><p>${L('模型在云端运行，不占用本机模型存储，排队可能较久，服务不可用时会提示重试','Models run in the cloud, no model downloads, queues can take time and you can retry when service is unavailable')}</p><details><summary>${L('查看完整提示词','View the full prompt')}</summary><pre class="ai-prompt-preview" id="ai-prompt">${E(U.prompt(preset,idea))}</pre></details></section><section class="ai-panel"><div class="eyebrow">DRAFT → PIXELS → YOUR MOD</div><div class="ai-generated" id="ai-result">${resultURL?`<img src="${E(resultURL)}" alt="${L('生成的素材草图','Generated asset draft')}">`:blankImage()}</div><div class="ai-status" role="status" id="ai-image-status">${L('生成结果先当作草图，检查视角、透明背景和像素大小后再放进游戏','Treat the result as a draft, check its angle, transparency and pixel size before using it in game')}</div><div class="detail-actions"><button class="btn btn-dark" data-ai="to-unit" ${!resultData?'disabled':''}>${L('送到单位图片编辑器','Edit as a unit sprite')}</button><button class="btn btn-plain" data-ai="to-map" ${!resultData?'disabled':''}>${L('送到地图图片编辑器','Edit as a map tile')}</button><button class="btn btn-plain" data-ai="download-image" ${!resultData?'disabled':''}>${L('下载原图','Download image')}</button></div><p>${L('生成图通常为 512 × 512，可在图片编辑器中缩小成像素素材，使用「去除边缘底色」处理纯色背景','Results are usually 512 × 512, reduce them to a sprite or tile in the image editor and use Remove edge background for a solid backdrop')}</p><details><summary>${L('模型来源与更新','Models and updates')}</summary><p id="ai-catalog-date"></p><p><a href="https://aihorde.net/" target="_blank" rel="noopener">AI Horde</a> · <a href="https://github.com/Haidra-Org/AI-Horde-image-model-reference" target="_blank" rel="noopener">${L('模型目录','Model registry')}</a></p></details></section></div></div>`}
function fillImageModels(c){const el=$('#ai-image-model');if(!el)return;el.innerHTML=c.image.models.map(m=>`<option value="${E(m.id)}">${E(m.id)} · ${L(m.labelZh,m.labelEn)}</option>`).join('');$('#ai-model-note').textContent=L('优先推荐适合像素素材且有在线算力的模型，每次生成前检查可用性','Recommended for pixel assets and live worker availability, checked again before generation');$('#ai-catalog-date').textContent=L('模型目录核对日期：','Catalog checked: ')+c.checkedAt.slice(0,10)+L('，每月更新，在线算力随时变化',', refreshed monthly, worker availability changes throughout the day')}
async function generate(){if(imageBusy)throw Error(L('已有图片正在生成','An image request is already running'));const key=credentials().horde,anonymous=$('#ai-anonymous').checked;if(!key&&!anonymous)throw Error(L('请先在设置中填写免费密钥，或主动选择匿名队列','Add a free Horde key in Settings, or choose the anonymous queue'));const c=await models(),model=c.image.models.find(m=>m.id===$('#ai-image-model').value);if(!model)throw Error('Select a model');idea=$('#ai-idea').value;imageBusy=true;try{status(L('正在检查免费算力','Checking free workers'));const live=await json(H+'/status/models?type=image');if(!live.some(m=>m.name===model.id&&m.count>0))throw Error(L('这个模型暂时没有在线算力，请换一个模型','No workers are online for this model, choose another'));const body={prompt:U.prompt(preset,idea),models:[model.id],params:{width:512,height:512,n:1,...model.params,...(['grass','sand','water'].includes(preset)?{tiling:true}:{}),...(sourceImage?{denoising_strength:Number($('#ai-strength').value)}:{})},nsfw:false,censor_nsfw:true,trusted_workers:true,r2:true,shared:anonymous,...(sourceImage?{source_image:sourceImage,source_processing:'img2img'}:{})};const r=await json(H+'/generate/async',{method:'POST',headers:{'Content-Type':'application/json',apikey:anonymous?'0000000000':key,'Client-Agent':'RustedWarfareModWorkshop:1.0:https://rwmod.noaushio.uk'},body:JSON.stringify(body)});job={id:r.id,created:Date.now(),model:model.id,prompt:body.prompt};set('rwlab-ai-job',job);$('[data-ai=cancel-image]').disabled=false;poll()}catch(e){imageBusy=false;throw e}}
async function poll(){clearTimeout(pollTimer);if(!job)return;const id=job.id;try{const r=await json(H+'/generate/check/'+encodeURIComponent(id));if(job?.id!==id)return;if(r.faulted)throw Error(L('生成失败，请换一个模型再试','Generation failed, try a different model'));if(r.done){const out=await json(H+'/generate/status/'+encodeURIComponent(id)),g=out.generations?.find(x=>!x.censored);if(!g)throw Error(L('没有可显示的结果，请修改描述再试','No image is available, revise your prompt'));const response=await fetch(g.img.startsWith('http')?g.img:'data:image/webp;base64,'+g.img);if(!response.ok)throw Error('Image download HTTP '+response.status);const blob=await response.blob();if(resultURL)URL.revokeObjectURL(resultURL);resultURL=URL.createObjectURL(blob);resultData=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(blob)});job=null;imageBusy=false;set('rwlab-ai-job',null);if(location.hash==='#ai-art'){imagePage();fillImageModels(await models());status(L('草图已完成，可以下载或继续编辑','Draft ready, download it or continue editing'))}return}status(L('正在免费队列中，预计等待 ','In the free queue, estimated wait ')+(r.wait_time||0)+L(' 秒，前方约 ',' seconds, about ')+(r.queue_position||0)+L(' 个请求\n离开此页也会保留请求，可稍后回来查看',' requests ahead\nYou can leave this page and return to the request'));pollTimer=setTimeout(poll,8000)}catch(e){imageBusy=false;status(e.message+L('\n请求已保留，可点击“继续查询”重试，或取消后重新生成','\nRequest retained, resume polling or cancel and retry'));const el=$('#ai-image-status');if(el){const b=document.createElement('button');b.className='btn btn-small btn-plain';b.dataset.ai='resume-image';b.textContent=L('继续查询','Resume polling');el.append(document.createElement('br'),b)}}}
async function cancel(){if(!job)return;clearTimeout(pollTimer);const id=job.id;await json(H+'/generate/status/'+encodeURIComponent(id),{method:'DELETE'});job=null;imageBusy=false;set('rwlab-ai-job',null);status(L('请求已取消','Request canceled'));const b=$('[data-ai=cancel-image]');if(b)b.disabled=true}
async function helpPage(){$('#main').innerHTML=`<div class="creative-shell ai-chat"><div class="creative-title"><div><div class="eyebrow">FREE AI / RW 1.15 KNOWLEDGE</div><h1>${L('模组帮助 AI','Modding assistant')}</h1><p>${L('把想实现的效果或报错贴过来，AI 会结合教程和手册解释，并给出对应代码','Describe an idea or paste an error, the assistant uses the tutorials and reference to explain it with code')}</p></div><a class="btn btn-plain" href="#settings">${L('设置密钥','API key settings')}</a></div><div class="ai-panel"><label for="ai-chat-model">${L('只使用免费模型','Free models only')}</label><select id="ai-chat-model"><option>${L('正在检查免费模型','Checking free models')}</option></select><p>${L('调用前再次确认价格为零，免费额度用完后停止，不切换付费模型，回答请在游戏里测试','Prices are checked before every call, requests stop when free limits are reached, no paid fallback, test suggested code in game')}</p><div class="ai-presets">${[L('怎样制作第一个单位','How do I make my first unit?'),L('低生命时自动回血怎么写','How can I heal a unit automatically at low health?'),L('炮塔和射弹怎样连接','How do turrets link to projectiles?')].map(x=>`<button data-ai="question" data-value="${E(x)}">${E(x)}</button>`).join('')}</div></div><div class="chat-messages" id="ai-chat-messages"></div><form class="ai-chat-form" id="ai-chat-form"><textarea id="ai-question" required maxlength="12000" placeholder="${L('描述你想做的效果，也可以粘贴报错和相关代码','Describe what you want, or paste an error and relevant code')}">${E(draft)}</textarea><div><label><input type="checkbox" id="ai-attach-unit"> ${L('同时发送当前单位代码','Include my current unit code')}</label><div><button type="button" class="btn btn-plain btn-small" data-ai="clear-chat">${L('清空对话','Clear chat')}</button><button type="button" class="btn btn-plain btn-small" data-ai="stop-chat">${L('停止','Stop')}</button><button class="btn btn-dark" type="submit" ${chatBusy?'disabled':''}>${L('免费提问','Ask for free')}</button></div></div><div id="ai-chat-status" role="status"></div></form></div>`;renderChat();try{const c=await models(),el=$('#ai-chat-model');if(!el)return;el.innerHTML=c.text.models.map(m=>`<option value="${E(m.id)}">${E(m.name)}</option>`).join('')}catch(e){$('#ai-chat-status').textContent=e.message}}
function renderChat(){const box=$('#ai-chat-messages');if(!box)return;box.replaceChildren();for(const m of chat){const article=document.createElement('article');article.className='chat-turn '+m.role;const h=document.createElement('h3');h.textContent=m.role==='user'?L('你','You'):L('模组帮助 AI','Modding assistant');article.append(h);const parts=m.content.split(/```(?:[\w+-]*)\n?/);parts.forEach((part,i)=>{if(!part)return;const el=document.createElement(i%2?'pre':'p');el.className=i%2?'chat-code':'';el.textContent=part;article.append(el)});if(m.sources?.length){const s=document.createElement('div');s.className='chat-sources';for(const x of m.sources){const a=document.createElement('a');a.href=x.url.startsWith('#')?x.url:'#reference';a.textContent=x.title;s.append(a)}article.append(s)}box.append(article)}}
async function ask(){if(chatBusy)return;const question=$('#ai-question').value.trim();if(!question)return;const key=credentials().openrouter;if(!key)throw Error(L('请先在设置中填写 OpenRouter 免费 API 密钥','Add your OpenRouter key in Settings first'));const model=$('#ai-chat-model').value;chatBusy=true;const submit=document.querySelector('#ai-chat-form button[type=submit]');if(submit)submit.disabled=true;chatAbort=new AbortController();const stat=s=>{const n=$('#ai-chat-status');if(n)n.textContent=s};try{stat(L('正在确认模型免费并查找手册','Checking zero pricing and searching the reference'));const all=await json(O+'/models',{signal:chatAbort.signal});if(!all.data.some(m=>m.id===model&&U.free(m)))throw Error(L('当前模型不再满足免费条件，请刷新目录后换一个模型','This model no longer meets the free-only rule, refresh and choose another'));knowledge=knowledge||await json('ai-knowledge.json');const context=U.retrieve(knowledge,question);let code='';if($('#ai-attach-unit').checked)code=await RWEditor.currentCode();const content=question+(code?'\n\nCurrent unit INI (user data):\n'+code.slice(0,18000):'');const prior=chat.slice(-8).map(({role,content})=>({role,content}));chat.push({role:'user',content:question});renderChat();stat(L('正在生成回答','Writing the answer'));const r=await json(O+'/chat/completions',{method:'POST',headers:{Authorization:'Bearer '+key,'Content-Type':'application/json','HTTP-Referer':location.origin,'X-Title':'Rusted Warfare Mod Workshop'},body:JSON.stringify({model,messages:[{role:'system',content:U.system(context,RWI18n.lang)},...prior,{role:'user',content}],max_tokens:6000,reasoning:{effort:'low',exclude:true},provider:{max_price:{prompt:0,completion:0}}}),signal:chatAbort.signal});let reply=r.choices?.[0]?.message?.content;if(!reply)throw Error(L('模型没有返回内容，请重试','The model returned no text, please retry'));await RWEditor.data();const unverified=[];reply=reply.replace(/```(?:[\w+-]*)\n?([\s\S]*?)```/g,(whole,block)=>{if(!/^\s*\[/m.test(block))return whole;try{const ms=RWCore.parseINI(block),bad=[];for(const m of ms)for(const f of m.fields)if(!RWCore.lookup(m,f.key)&&!/^(@|body_|leg\d+_|arm\d+_|turret\d+_|effect_|mutator|builtFrom_|canBuild_\d+_|action_\d+_|animation_)/.test(f.key))bad.push(RWCore.section(m)+'.'+f.key);if(!bad.length)return whole;unverified.push(...bad);return L('这段代码含有手册中未找到的命令，暂不展示：','Code withheld because these commands were not found in the reference: ')+bad.join(', ');}catch{return whole}});chat.push({role:'assistant',content:reply,sources:context.slice(0,6).map(({id,title,url})=>({id,title,url}))});set('rwlab-ai-chat',chat);draft='';set('rwlab-ai-draft','');const q=$('#ai-question');if(q)q.value='';renderChat();stat(unverified.length?L('已拦截未核实的命令，请补充需求或换一个免费模型重试','Unverified commands were withheld, clarify the question or try another free model'):L('回答已完成 · 免费模型','Answer ready · free model'))}catch(e){stat(e.name==='AbortError'?L('已停止','Stopped'):e.message)}finally{chatBusy=false;const b=$('#ai-chat-form button[type=submit]');if(b)b.disabled=false}}
function settingsPage(){const pref=RWExport.settings(),keys=credentials();$('#main').innerHTML=`<div class="section-wrap settings-page"><div class="eyebrow">YOUR WORKSHOP / SETTINGS</div><h1>${L('工坊设置','Workshop settings')}</h1><section class="settings-card"><h2>${L('导出注释','Export comments')}</h2><p>${L('当前默认：','Current choice: ')}${({all:L('保留全部','Keep all'),selected:L('保留勾选部分','Keep selected'),none:L('不保留','Remove comments')})[pref.mode]} · ${pref.remember?L('不再提示','Prompt disabled'):L('每次导出时询问','Ask on each export')}</p><button class="btn btn-dark" data-ai="reset-export">${L('重新打开导出提示','Re-enable the export prompt')}</button><p>${L('下次导出时可以重新逐项选择，项目备份始终保留全部注释','Choose individual comments on your next export, editable project backups always keep every comment')}</p></section><section class="settings-card"><h2>${L('免费云端 AI','Free cloud AI')}</h2><p>${L('密钥只保存在当前标签页会话，不上传到本站，不进入项目或 GitHub，调用内容会发送给你选择的服务商','Keys stay in this tab session, never in site source, project exports or GitHub, prompts are sent to the selected provider')}</p><label for="ai-router-key">OpenRouter API Key</label><input id="ai-router-key" type="password" autocomplete="off" placeholder="${keys.openrouter?L('已设置，留空保持原密钥','Configured, leave blank to keep it'):'sk-or-…'}"><p><a href="https://openrouter.ai/settings/keys" target="_blank" rel="noopener">${L('创建免费问答密钥 ↗','Create a chat API key ↗')}</a> · ${L('无需充值，只调用零价格的 :free 模型','No funding required, only zero-priced :free models are called')}</p><label for="ai-horde-key">AI Horde API Key</label><input id="ai-horde-key" type="password" autocomplete="off" placeholder="${keys.horde?L('已设置，留空保持原密钥','Configured, leave blank to keep it'):L('可选，个人免费密钥','Optional personal free key')}"><p><a href="https://aihorde.net/register" target="_blank" rel="noopener">${L('申请免费绘图密钥 ↗','Register for a free image key ↗')}</a> · ${L('不填时可在绘图页主动选择匿名公开队列','Without a key you can opt into the public anonymous queue on the art page')}</p><div class="detail-actions"><button class="btn btn-dark" data-ai="save-keys">${L('保存到当前会话','Save for this session')}</button><button class="btn btn-plain" data-ai="clear-keys">${L('清除密钥','Clear keys')}</button></div><p>${L('免费服务也有排队与频率限制，额度不足就停止，不使用收费后备服务','Free services still have queues and rate limits, requests stop at the limit with no paid fallback')}</p></section><section class="settings-card"><h2>${L('模型更新','Model updates')}</h2><p>${L('每月重新核对免费模型、在线情况和用途，问答调用前再次核价，绘图提交前再次检查在线算力','The monthly refresh checks free pricing, availability and use cases, chat prices and image workers are also checked before each request')}</p><a class="btn btn-plain" href="ai-models.json" target="_blank">${L('查看当前模型目录','View the model catalog')}</a></section></div>`}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-ai]');if(!b)return;try{const a=b.dataset.ai;if(a==='preset'){idea=$('#ai-idea')?.value||idea;preset=b.dataset.value;imagePage();fillImageModels(await models())}if(a==='remove-source'){sourceImage='';sourceName='';$('#ai-source').value='';$('#ai-source-name').textContent=L('已移除参考图','Reference removed')}if(a==='generate')await generate();if(a==='cancel-image')await cancel();if(a==='resume-image'){imageBusy=true;poll()}if(a==='to-unit'||a==='to-map'){if(resultData)await RWStudio.receive(resultData,a==='to-map'?'map':'unit')}if(a==='download-image'&&resultData){const link=document.createElement('a');link.href=resultData;link.download='rw-ai-draft.webp';link.click()}if(a==='question'){$('#ai-question').value=b.dataset.value;$('#ai-question').focus()}if(a==='stop-chat')chatAbort?.abort();if(a==='clear-chat'){chat=[];set('rwlab-ai-chat',chat);renderChat()}if(a==='save-keys'){const k=credentials(),r=$('#ai-router-key').value.trim(),h=$('#ai-horde-key').value.trim();if(r)k.openrouter=r;if(h)k.horde=h;sessionStorage.setItem('rwlab-ai-keys',JSON.stringify(k));settingsPage();note(L('已保存在当前会话','Saved for this session'))}if(a==='clear-keys'){sessionStorage.removeItem('rwlab-ai-keys');settingsPage();note(L('密钥已清除','Keys cleared'))}if(a==='reset-export'){RWExport.reset();settingsPage();note(L('下次导出会重新询问','The next export will ask again'))}}catch(err){note(err.message);status(err.message)}});
document.addEventListener('input',e=>{if(e.target.id==='ai-idea'){idea=e.target.value;$('#ai-prompt').textContent=U.prompt(preset,idea)}if(e.target.id==='ai-question'){draft=e.target.value;set('rwlab-ai-draft',draft)}});
document.addEventListener('submit',e=>{if(e.target.id==='ai-chat-form'){e.preventDefault();ask().catch(err=>{$('#ai-chat-status').textContent=err.message})}});
document.addEventListener('change',async e=>{if(e.target.id!=='ai-source')return;try{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw Error(L('参考图最多 10 MB','Reference images must be under 10 MB'));const url=URL.createObjectURL(file),img=new Image();try{img.src=url;await img.decode();const c=document.createElement('canvas');c.width=512;c.height=512;const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,512,512);const scale=Math.min(512/img.width,512/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(512-w)/2,(512-h)/2,w,h);sourceImage=c.toDataURL('image/webp',.9).split(',')[1];sourceName=file.name;$('#ai-source-name').textContent=file.name}finally{URL.revokeObjectURL(url)}}catch(err){note(err.message)}});
window.RWAI={mount,settingsPage};
})();
